/* eslint-env serviceworker */
/* global clients */

/**
 * Web Push handlers, imported into the generated service worker.
 *
 * This lives as its own file rather than inside the worker because the worker
 * is GENERATED by vite-plugin-pwa (`generateSW`), so there is no source file to
 * edit — `workbox.importScripts` in vite.config.js pulls this in. Keeping the
 * push logic out of the build also means it can be read and reasoned about
 * without digging through a bundled artefact.
 *
 * Nothing here touches the cache. The worker's caching contract — precache the
 * shell, never intercept /api/* — is unchanged by anything in this file.
 */

self.addEventListener('push', (event) => {
  // A push with no payload still means something happened. Show the generic
  // line rather than nothing: a silent push that the browser then reports as
  // "this site was updated in the background" is worse than a vague one.
  let payload = {};
  if (event.data) {
    try {
      payload = event.data.json();
    } catch {
      payload = { body: event.data.text() };
    }
  }

  const title = payload.title || 'Macan';
  const options = {
    body: payload.body || 'You have a new notification',
    icon: '/icon-192.png',
    badge: '/icon-192.png',
    // Repeats about the same task replace each other instead of stacking five
    // lock-screen rows for five edits of one row.
    tag: payload.tag || 'macan',
    renotify: true,
    data: { url: payload.url || '/', notificationId: payload.notificationId },
  };

  event.waitUntil(self.registration.showNotification(title, options));
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();

  const target = event.notification.data?.url || '/';

  event.waitUntil(
    (async () => {
      const windows = await clients.matchAll({
        type: 'window',
        includeUncontrolled: true,
      });

      // Reuse a Macan that is already open rather than opening a fourth copy.
      // `navigate` keeps the SPA's session and stores warm; a fresh window
      // would re-boot the whole app to land on the same row.
      for (const client of windows) {
        if (new URL(client.url).origin === self.location.origin) {
          await client.focus();
          if ('navigate' in client) {
            try {
              await client.navigate(target);
            } catch {
              /* some browsers refuse navigate() on a focused client; the
                 focus alone is still the right outcome */
            }
          }
          return;
        }
      }

      await clients.openWindow(target);
    })()
  );
});
